import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"接入模型","description":"配置对话模型、四种协议和 Codex 执行器。","frontmatter":{"title":"接入模型","description":"配置对话模型、四种协议和 Codex 执行器。","outline":[2,3]},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md","lastUpdated":null}'),r={name:"guide/models.md"};function c(i,t,n,h,s,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="接入模型" tabindex="-1">接入模型 <a class="header-anchor" href="#接入模型" aria-label="Permalink to &quot;接入模型&quot;">​</a></h1><p class="lead">Hearth 把“聊天模型”和“Codex 执行器”分开配置。聊天模型负责原生 Agent Runtime 的推理与工具调用；Codex 执行器负责代码和仓库任务。</p><h2 id="对话模型" tabindex="-1">对话模型 <a class="header-anchor" href="#对话模型" aria-label="Permalink to &quot;对话模型&quot;">​</a></h2><p>进入 <strong>设置 → 对话模型</strong>，选择预设或自定义服务：</p><table tabindex="0"><thead><tr><th>预设</th><th>协议</th><th>默认 Base URL</th></tr></thead><tbody><tr><td>DeepSeek</td><td>OpenAI Chat</td><td><code>https://api.deepseek.com/v1</code></td></tr><tr><td>阿里云百炼</td><td>OpenAI Chat</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td>智谱 GLM</td><td>OpenAI Chat</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>月之暗面 Kimi</td><td>OpenAI Chat</td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>火山方舟</td><td>OpenAI Chat</td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr><tr><td>OpenAI</td><td>OpenAI Chat</td><td><code>https://api.openai.com/v1</code></td></tr><tr><td>Anthropic</td><td>Anthropic Messages</td><td><code>https://api.anthropic.com/v1</code></td></tr><tr><td>Google Gemini</td><td>Gemini</td><td><code>https://generativelanguage.googleapis.com/v1beta</code></td></tr><tr><td>自定义服务</td><td>任选四种协议</td><td>由你填写</td></tr></tbody></table><p>四种协议由 <code>@hearth/model-client</code> 统一成同一种流式 Agent 回合：文本增量、工具调用、参数拼接、结束原因和用量。更换服务商不会改变 Runtime 的工具循环。</p><h3 id="密钥如何保存" tabindex="-1">密钥如何保存 <a class="header-anchor" href="#密钥如何保存" aria-label="Permalink to &quot;密钥如何保存&quot;">​</a></h3><p>密钥写入 <code>.hearth/model-settings.json</code>，文件权限尽量设为 <code>0600</code>。设置接口只返回掩码，例如 <code>sk-1••••abcd</code>，不会把原始密钥返回浏览器。</p><h3 id="模型必须支持工具调用" tabindex="-1">模型必须支持工具调用 <a class="header-anchor" href="#模型必须支持工具调用" aria-label="Permalink to &quot;模型必须支持工具调用&quot;">​</a></h3><p>原生执行器依赖模型返回结构化工具调用。如果所选模型不支持工具调用，Hearth 会给出明确错误，不会把普通文本回答伪装成任务完成。</p><h2 id="codex-执行器" tabindex="-1">Codex 执行器 <a class="header-anchor" href="#codex-执行器" aria-label="Permalink to &quot;Codex 执行器&quot;">​</a></h2><p>Codex 执行器读取现有的 <code>~/.codex/config.toml</code>，不要求 <code>codex login</code>。只要配置了 <code>model_provider</code> 和对应的 <code>env_key</code>，并让该环境变量存在于启动 Hearth 的终端中即可。</p><p>设置页会显示：</p><ul><li>Provider 与模型。</li><li>Base URL 与 wire API。</li><li>环境变量名以及是否已读取。</li><li>配置文件路径与当前问题列表。</li></ul><p>修改 <code>config.toml</code> 或环境变量后，点 <strong>重新检测</strong> 即可，不需要重启服务。</p><h3 id="双执行器如何选择" tabindex="-1">双执行器如何选择 <a class="header-anchor" href="#双执行器如何选择" aria-label="Permalink to &quot;双执行器如何选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>执行器</th><th>适用任务</th><th>默认行为</th></tr></thead><tbody><tr><td><code>native</code></td><td>通用整理、分析、写作、简单文件处理</td><td>普通任务默认走原生 Runtime</td></tr><tr><td><code>codex</code></td><td>代码仓库、多文件修改、运行测试、提交改动</td><td>明确的工程任务走 Codex</td></tr></tbody></table><p>两者不会在失败后静默互换。运行清单会记录实际执行器，便于核对任务到底由谁完成。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>保存后仍显示未配置？</strong> 检查 Base URL、模型名和 API Key 是否都非空，然后点 <strong>测试连接</strong>。</p><p><strong>Codex 显示未连接？</strong> 检查 <code>env_key</code> 指向的环境变量是否存在于启动 Hearth 的终端。Windows 用户环境变量修改后需要重新打开终端或重启服务。</p><p><strong>能同时用两家模型吗？</strong> 当前设置保存一组对话模型配置。不同任务可以使用不同执行器，但对话模型是全局配置。</p>',22)])])}const g=e(r,[["render",c]]);export{m as __pageData,g as default};
